void WaveWriter::header(uint32_t size){auto u16=[&](uint16_t v){file.write((char*)&v,2);};auto u32=[&](uint32_t v){file.write((char*)&v,4);};file.seekp(0);file.write("RIFF",4);u32(size+36);file.write("WAVEfmt ",8);u32(16);u16(1);u16(channels);u32(rate);u32(rate*channels*3);u16(channels*3);u16(24);file.write("data",4);u32(size);}
WaveWriter::WaveWriter(const fs::path&path,int sampleRate,int channelCount):file(path,std::ios::binary),rate(sampleRate),channels(channelCount){if(channels!=1&&channels!=2)throw std::runtime_error("Recording needs one or two channels");if(!file)throw std::runtime_error("Cannot create recorded WAV");header(0);}
WaveWriter::~WaveWriter(){try{finish();}catch(...){}}
void WaveWriter::write(const float*left,const float*right,int frames){if(finished)throw std::runtime_error("Recording is already closed");if((count+frames)*channels*3>512ull*1024*1024)throw std::runtime_error("Recording reached the 512 MB take limit");std::array<char,MaxBlock*6>bytes{};for(int offset=0;offset<frames;){int n=std::min(MaxBlock,frames-offset);for(int i=0;i<n;i++)for(int c=0;c<channels;c++){float value=c?right[offset+i]:left[offset+i];int32_t v=(int32_t)(clamp(std::isfinite(value)?value:0,-1,1)*8388607.);memcpy(bytes.data()+i*channels*3+c*3,&v,3);}file.write(bytes.data(),n*channels*3);if(!file)throw std::runtime_error("Recording disk write failed");count+=n;offset+=n;}if(count-lastHeader>=(uint64_t)rate){header((uint32_t)(count*channels*3));file.seekp(0,std::ios::end);file.flush();lastHeader=count;}}
void WaveWriter::finish(){if(finished)return;header((uint32_t)(count*channels*3));file.flush();if(!file)throw std::runtime_error("Cannot finish recorded WAV");file.close();finished=true;}
AudioCapture::AudioCapture(){stopEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);}
AudioCapture::~AudioCapture(){stop();CloseHandle(stopEvent);}
void AudioCapture::start(const std::wstring&id,double rate,const fs::path&recordPath){stop();device=id;sampleRate=rate;monitor.reset(std::max(512,(int)rate/30));diskQueue.reset();recordedFrames=0;capturedFrames=0;discontinuities=0;droppedPackets=0;diskStop=false;state=0;if(!recordPath.empty()){writer=std::make_unique<WaveWriter>(recordPath,(int)rate);diskWorker=std::thread([this]{diskRun();});}ResetEvent(stopEvent);worker=std::thread([this]{run();});}
void AudioCapture::stop(){if(worker.joinable()){SetEvent(stopEvent);worker.join();}diskStop=true;if(diskWorker.joinable())diskWorker.join();writer.reset();peak=0;if(state>=0)state=0;}
void AudioCapture::startExternal(double rate,const fs::path&recordPath,int channels){stop();sampleRate=rate;monitor.reset(std::max(512,(int)rate/30));diskQueue.reset();recordedFrames=0;capturedFrames=0;discontinuities=0;droppedPackets=0;diskStop=false;peakHistoryCount=0;for(auto&v:peakHistory)v=0;if(!recordPath.empty()){writer=std::make_unique<WaveWriter>(recordPath,(int)rate,channels);diskWorker=std::thread([this]{diskRun();});}state=1;}
void AudioCapture::ingest(const float*left,const float*right,int frames){if(state!=1)return;Packet packet;packet.frames=std::min(frames,MaxBlock);packet.startFrame=capturedFrames;float blockPeak=0;for(int i=0;i<packet.frames;i++){packet.left[i]=left?left[i]:0;packet.right[i]=right?right[i]:packet.left[i];blockPeak=std::max(blockPeak,std::max(std::abs(packet.left[i]),std::abs(packet.right[i])));}capturedFrames+=packet.frames;peak=blockPeak;auto history=peakHistoryCount.load(std::memory_order_relaxed);peakHistory[history%peakHistory.size()].store(blockPeak,std::memory_order_relaxed);peakHistoryFrame[history%peakHistory.size()].store(capturedFrames.load(),std::memory_order_relaxed);peakHistoryCount.store(history+1,std::memory_order_release);if(writer&&!diskQueue.push(packet))droppedPackets++;}
void AudioCapture::diskRun(){Packet packet;std::array<float,MaxBlock>silence{};bool failed=false;auto pad=[&](uint64_t target){while(writer->frames()<target){int n=(int)std::min<uint64_t>(MaxBlock,target-writer->frames());writer->write(silence.data(),silence.data(),n);}};while(true){if(diskQueue.pop(packet)){if(!failed)try{pad(packet.startFrame);writer->write(packet.left.data(),packet.right.data(),packet.frames);recordedFrames=writer->frames();}catch(...){failed=true;state=-5;}continue;}if(diskStop.load())break;Sleep(2);}if(!failed)try{pad(capturedFrames);recordedFrames=writer->frames();writer->finish();}catch(...){state=-5;}}
void AudioCapture::read(float*left,float*right,int frames){frames=std::min(frames,MaxBlock);monitor.read(monitorBuffer.data(),frames);for(int i=0;i<frames;i++){left[i]=monitorBuffer[i*2];right[i]=monitorBuffer[i*2+1];}}
void AudioCapture::run(){CoInitializeEx(nullptr,COINIT_MULTITHREADED);DWORD index=0;HANDLE task=AvSetMmThreadCharacteristicsW(L"Pro Audio",&index);IMMDeviceEnumerator*enumerator=nullptr;IMMDevice*endpoint=nullptr;IAudioClient*client=nullptr;IAudioCaptureClient*capture=nullptr;HANDLE ready=CreateEventW(nullptr,FALSE,FALSE,nullptr);
    auto cleanup=[&]{if(client)client->Stop();if(capture)capture->Release();if(client)client->Release();if(endpoint)endpoint->Release();if(enumerator)enumerator->Release();CloseHandle(ready);if(task)AvRevertMmThreadCharacteristics(task);CoUninitialize();};
    HRESULT hr=CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_ALL,__uuidof(IMMDeviceEnumerator),(void**)&enumerator);if(SUCCEEDED(hr))hr=device.empty()?enumerator->GetDefaultAudioEndpoint(eCapture,eConsole,&endpoint):enumerator->GetDevice(device.c_str(),&endpoint);if(SUCCEEDED(hr))hr=endpoint->Activate(__uuidof(IAudioClient),CLSCTX_ALL,nullptr,(void**)&client);
    WAVEFORMATEX format{};format.wFormatTag=WAVE_FORMAT_IEEE_FLOAT;format.nChannels=2;format.nSamplesPerSec=(DWORD)sampleRate;format.wBitsPerSample=32;format.nBlockAlign=8;format.nAvgBytesPerSec=format.nSamplesPerSec*8;
    if(SUCCEEDED(hr))hr=client->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_EVENTCALLBACK|AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM|AUDCLNT_STREAMFLAGS_SRC_DEFAULT_QUALITY,0,0,&format,nullptr);
    if(SUCCEEDED(hr))hr=client->SetEventHandle(ready);if(SUCCEEDED(hr))hr=client->GetService(__uuidof(IAudioCaptureClient),(void**)&capture);REFERENCE_TIME streamLatency=0;if(SUCCEEDED(hr)){client->GetStreamLatency(&streamLatency);latencyMs=streamLatency/10000.;hr=client->Start();}if(FAILED(hr)){state=-1;cleanup();return;}state=1;Packet packet;
    HANDLE waits[]={stopEvent,ready};DWORD waitResult=WAIT_OBJECT_0;bool firstPacket=true;UINT64 basePosition=0;while((waitResult=WaitForMultipleObjects(2,waits,FALSE,2000))==WAIT_OBJECT_0+1){UINT32 available=0;hr=capture->GetNextPacketSize(&available);if(FAILED(hr))break;while(available){BYTE*buffer=nullptr;UINT32 frames=0;DWORD flags=0;UINT64 position=0;hr=capture->GetBuffer(&buffer,&frames,&flags,&position,nullptr);if(FAILED(hr))break;if(firstPacket){basePosition=position;firstPacket=false;}else if(flags&AUDCLNT_BUFFERFLAGS_DATA_DISCONTINUITY)discontinuities++;uint64_t packetStart=position>=basePosition?position-basePosition:capturedFrames.load();capturedFrames=std::max(capturedFrames.load(),packetStart);float blockPeak=0;
            for(UINT32 offset=0;offset<frames;){packet.frames=(int)std::min<UINT32>(MaxBlock,frames-offset);packet.startFrame=capturedFrames;for(int i=0;i<packet.frames;i++){Stereo sample;if(!(flags&AUDCLNT_BUFFERFLAGS_SILENT)){memcpy(&sample.left,buffer+(offset+i)*8,4);memcpy(&sample.right,buffer+(offset+i)*8+4,4);if(!std::isfinite(sample.left))sample.left=0;if(!std::isfinite(sample.right))sample.right=0;}packet.left[i]=sample.left;packet.right[i]=sample.right;blockPeak=std::max(blockPeak,std::max(std::abs(sample.left),std::abs(sample.right)));}monitor.push(packet.left.data(),packet.right.data(),packet.frames);capturedFrames+=packet.frames;if(writer&&!diskQueue.push(packet))droppedPackets++;offset+=packet.frames;}peak=blockPeak;hr=capture->ReleaseBuffer(frames);if(FAILED(hr))break;hr=capture->GetNextPacketSize(&available);if(FAILED(hr))break;}if(FAILED(hr))break;}
    if(state!=-5)state=FAILED(hr)||waitResult==WAIT_TIMEOUT||waitResult==WAIT_FAILED?-4:0;cleanup();
}
